const raw = $input.first().json;
const reviews = Array.isArray(raw) ? raw : [raw];

// Group by business name
const businesses = {};
for (const review of reviews) {
  const name = review.businessName || 'Unknown';
  if (!businesses[name]) {
    businesses[name] = { reviews: [], totalRating: 0, platforms: new Set() };
  }
  businesses[name].reviews.push(review);
  businesses[name].totalRating += review.rating || 0;
  businesses[name].platforms.add(review.platform || 'Unknown');
}

// Build per-business report data
const reports = Object.entries(businesses).map(([name, data]) => {
  const total = data.reviews.length;
  const avgRating = total > 0 ? (data.totalRating / total).toFixed(1) : 0;
  const negCount = data.reviews.filter(r => r.rating <= 2).length;
  const posCount = data.reviews.filter(r => r.rating >= 4).length;
  const recentReviews = data.reviews.slice(0, 5).map(r => `⭐${r.rating} — ${(r.reviewText || '').slice(0, 80)}...`).join('\n');

  const html = `<div style='border:1px solid #ddd;padding:16px;margin-bottom:16px;border-radius:8px;'>
    <h3>${name}</h3>
    <p>📊 <strong>This week:</strong> ${total} reviews · Avg Rating: <strong>${avgRating}★</strong></p>
    <p>✅ Positive (4-5★): ${posCount} &nbsp; ⚠️ Negative (1-2★): ${negCount}</p>
    <p>🌐 Platforms: ${[...data.platforms].join(', ')}</p>
    <h4>Recent Reviews:</h4>
    <pre style='background:#f9f9f9;padding:8px;font-size:12px;'>${recentReviews}</pre>
  </div>`;

  return { json: { businessName: name, totalReviews: total, avgRating, negCount, posCount, html } };
});

return reports;

const reports = $input.first().json.allReports || [];
const weekOf = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
const htmlSections = reports.map(r => r.html).join('');
const totalReviews = reports.reduce((sum, r) => sum + (r.totalReviews || 0), 0);

const html = `<!DOCTYPE html><html><body style='font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;'>
  <h1 style='color:#1a1a2e;'>📊 Weekly Reputation Report</h1>
  <p style='color:#666;'>Week ending: ${weekOf}</p>
  <p><strong>${reports.length} businesses monitored</strong> · <strong>${totalReviews} total reviews</strong> this week</p>
  <hr/>
  ${htmlSections}
  <hr/>
  <p style='color:#999;font-size:12px;'>Powered by Prime Automate Systems · conceivable_extension/multi-platform-review-scraper</p>
</body></html>`;

return [{ json: { html, subject: `📊 Weekly Reputation Report — Week of ${weekOf}` } }];
